    void theCorporatePlanNeedsTheCodeOfACompanyWithAnAgreement() {
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.CORPORATE))));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() ->
                service.create(stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.CORPORATE, "TECNOSU"))));

        Reservation reservation =
                service.create(stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.CORPORATE, "TECNOSUL"));

        assertEquals(new BigDecimal("686.22"), reservation.price().total());
    }

    \@Test
    void theWeekendPackageOnlyGoesFromFridayToTheSundayRightAfter() {
        // 2027-03-12 is a Friday, and 2027-03-14 the Sunday right after it
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() ->
                service.create(stay(201, "2027-03-11", "2027-03-13", 2, RatePlan.WEEKEND_PACKAGE))));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() ->
                service.create(stay(201, "2027-03-12", "2027-03-13", 2, RatePlan.WEEKEND_PACKAGE))));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() ->
                service.create(stay(201, "2027-03-12", "2027-03-15", 2, RatePlan.WEEKEND_PACKAGE))));

        Reservation reservation =
                service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.WEEKEND_PACKAGE));

        assertEquals(new BigDecimal("820.00"), reservation.price().total());
    }

    \@Test
    void theLongStayPlanNeedsSevenNights() {
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() ->
                service.create(stay(101, "2027-03-01", "2027-03-07", 2, RatePlan.LONG_STAY))));

        Reservation reservation = service.create(stay(101, "2027-03-01", "2027-03-08", 2, RatePlan.LONG_STAY));

        assertEquals(new BigDecimal("1574.37"), reservation.price().total());
    }

    \@Test
    void theNewPlansGiveTheirOwnMoneyBackOnCancellation() {
        Reservation corporate =
                service.create(stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.CORPORATE, "TECNOSUL"));
        Reservation weekend = service.create(stay(202, "2027-03-12", "2027-03-14", 2, RatePlan.WEEKEND_PACKAGE));
        Reservation longStay = service.create(stay(101, "2027-03-01", "2027-03-08", 2, RatePlan.LONG_STAY));
        service.confirm(corporate.id());
        service.confirm(weekend.id());
        service.confirm(longStay.id());

        assertEquals(new BigDecimal("686.22"), service.cancel(corporate.id()).refund());
        assertEquals(new BigDecimal("410.00"), service.cancel(weekend.id()).refund());
        assertEquals(new BigDecimal("1574.37"), service.cancel(longStay.id()).refund());
        assertEquals(new BigDecimal("410.00"), weekend.amountKept());
    }

